// Class 12 English Core - Flamingo Prose Chapter 4: The Rattrap
// Fully standardized to English Core Blueprint & AGENTS.md guidelines

export const c12EngF4HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.8; color: #E2E8F0; max-width: 950px; margin: 0 auto; padding: 12px; font-size: 15.5px;\">\n\n  <!-- Chapter Header Badge -->\n  <div style=\"background: linear-gradient(135deg, rgba(142, 45, 226, 0.22), rgba(74, 0, 224, 0.1)); border: 1.5px solid #8E2DE2; border-radius: 12px; padding: 20px; margin-bottom: 25px; box-shadow: 0 4px 22px rgba(142, 45, 226, 0.15);\">\n    <div style=\"display: flex; align-items: center; gap: 10px; margin-bottom: 8px;\">\n      <span style=\"background: #8E2DE2; color: #FFFFFF; font-size: 12px; font-weight: 800; padding: 4px 10px; border-radius: 6px; letter-spacing: 0.5px;\">FLAMINGO &bull; PROSE CHAPTER 4</span>\n      <span style=\"color: #94A3B8; font-size: 13.5px; font-weight: 600;\">CLASS XII ENGLISH CORE</span>\n    </div>\n    <h1 style=\"color: #FFFFFF; font-size: 26px; font-weight: 900; margin: 0 0 6px 0; letter-spacing: -0.5px;\">The Rattrap</h1>\n    <p style=\"color: #CBD5E1; font-size: 15px; margin: 0; font-style: italic;\">\n      By Selma Lagerl&ouml;f (1858&ndash;1940, Sweden) &mdash; First Female Nobel Laureate in Literature (1909): Human Dignity, Christian Grace &amp; Moral Redemption\n    </p>\n  </div>\n\n  <!-- Quick Glossary & Chapter Dossier Card -->\n  <div style=\"background: rgba(15, 23, 42, 0.92); border: 1.5px solid rgba(142, 45, 226, 0.4); border-radius: 10px; padding: 18px 20px; margin-bottom: 25px; box-shadow: 0 4px 20px rgba(0,0,0,0.35);\">\n    <h3 style=\"color: #8E2DE2; font-size: 18px; margin: 0 0 12px 0; display: flex; align-items: center; gap: 8px;\">\n      <span>📖</span> Quick Glossary &amp; Chapter Dossier: The Rattrap\n    </h3>\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; font-size: 14px; color: #CBD5E1;\">\n      <div><b style=\"color: #8E2DE2;\">Author:</b> Selma Lagerl&ouml;f (Swedish Master; Nobel Prize in Literature 1909)</div>\n      <div><b style=\"color: #8E2DE2;\">Genre:</b> Allegorical Fairy-Tale with Realist Social Backdrop</div>\n      <div><b style=\"color: #8E2DE2;\">Setting:</b> Mining District of Bergslagen &amp; Ramsj&ouml; Ironworks, Sweden</div>\n      <div><b style=\"color: #8E2DE2;\">The Extended Metaphor:</b> The world is a giant rattrap setting baits of wealth, food &amp; shelter</div>\n      <div><b style=\"color: #8E2DE2;\">The Bait:</b> Thirty kronor stolen from the hospitable, lonely old crofter</div>\n      <div><b style=\"color: #8E2DE2;\">The Ironmaster:</b> Status-conscious forge owner mistaking the peddler for Captain von Stahle</div>\n      <div><b style=\"color: #8E2DE2;\">Edla Willmansson:</b> Compassionate daughter whose unconditional love redeems the vagabond</div>\n      <div><b style=\"color: #8E2DE2;\">The Transformation:</b> Signed as \"Captain von Stahle\", returning the 30 kronor with a gifted rattrap</div>\n    </div>\n  </div>\n\n  <!-- Section 1: Executive Summary & Philosophical Framework -->\n  <h2 style=\"color: #8E2DE2; font-size: 20px; font-weight: 800; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    1. Executive Summary &amp; Philosophical Framework\n  </h2>\n  <p>\n    In <b style=\"color: #8E2DE2;\">The Rattrap</b>, Swedish Nobel Laureate <b style=\"color: #8E2DE2;\">Selma Lagerl&ouml;f</b> constructs a radiant, morally profound allegory disguised as a winter fairy tale. Set amidst the snow-blanketed iron ore country of Sweden, the story follows a homeless vagabond who survives by hawking wire rattraps, begging, and committing petty theft. Embittered by the cruelty of the world, he formulates a cynical philosophical paradigm: the whole cosmos is merely an enormous rattrap offering riches, food, and shelter as seductive bait to entrap greedy humans.\n  </p>\n  <p>\n    When the peddler succumbs to temptation himself by stealing thirty kronor from an affectionate, lonely crofter, he finds his cynical worldview turning into an agonizing reality inside an impenetrable forest maze. His salvation occurs not through punitive law or righteous condemnation, but through the transformative grace of <b style=\"color: #8E2DE2;\">Edla Willmansson</b>. By treating a wretched thief with the unearned honor, dignity, and hospitality due to a military captain, Edla unlocks the latent kernel of nobility in his soul, proving that <b style=\"color: #8E2DE2;\">essential goodness can always be reawakened through unconditional love</b>.\n  </p>\n\n  <!-- Section 2: Narrative Arc -->\n  <h2 style=\"color: #8E2DE2; font-size: 20px; font-weight: 800; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    2. Deep Narrative Analysis: The Journey of Spiritual Metamorphosis\n  </h2>\n\n  <h3 style=\"color: #8E2DE2; font-size: 17px; margin: 20px 0 10px 0;\">(i) The Cynical Tramp &amp; The Philosophy of the Rattrap</h3>\n  <p>\n    The protagonist is an unnamed peddler who wanders the roads selling small rattraps bent from scrap wire. Because the trade fails to keep him fed, he resorts to begging and petty thievery. His clothes are tattered rags, his hollow cheeks betray chronic hunger, and his eyes gleam with starved desperation.\n  </p>\n  <p>\n    One gloomy winter afternoon, trudging through the snow, an eccentric meditation strikes his fancy: <b style=\"color: #8E2DE2;\">the entire world is nothing but a giant rattrap</b>. It exists for no other purpose than to set baits for people. Just as a wire trap offers cheese rinds and bits of pork to lure innocent rats, the world flaunts riches, lands, shelter, warmth, and food. As soon as a person is seduced and touches the bait, the trap snaps shut, sealing them in terminal despair. Having been treated with contempt by humanity, thinking ill of the world in this manner affords the vagabond malicious, soothing delight.\n  </p>\n\n  <h3 style=\"color: #8E2DE2; font-size: 17px; margin: 20px 0 10px 0;\">(ii) Betrayed Hospitality: The Old Crofter's Cottage</h3>\n  <p>\n    Seeking refuge from the biting cold at twilight, he knocks on a humble gray cottage beside the road. Instead of the sour grimaces he customarily receives, he is warmly welcomed by an old crofter living in complete isolation without wife or offspring. Starved of human companionship, the lonely crofter treats the tramp like an honored guest &mdash; heating porridge over the fire, carving a massive chunk from his tobacco roll for their pipes, and playing the Swedish card game <i>mj&ouml;lis</i> late into the night.\n  </p>\n  <p>\n    In an overflow of childlike trust, the crofter discloses his financial secrets: in his youth, he had been a tenant worker at Ramsj&ouml; Ironworks; now his extraordinary cow supports him, providing milk that earned him thirty kronor the previous month. Noticing the peddler’s skeptical frown, the crofter steps to the window, takes down a leather pouch from a wooden nail, counts out three wrinkled ten-kronor notes before the tramp's eyes, and deposits them back.\n  </p>\n  <p>\n    The following morning, both men depart amiably. However, half an hour later, greed overpowers the peddler. He returns, smashes the windowpane with his hand, reaches through the jagged glass, snatches the thirty kronor, and disappears into the woods, delighted with his cunning larceny.\n  </p>\n\n  <h3 style=\"color: #8E2DE2; font-size: 17px; margin: 20px 0 10px 0;\">(iii) The Forest Labyrinth: Caught in His Own Trap</h3>\n  <p>\n    Dreading detection by constables on the public highway, the thief plunges into the thick, pathless woods. At first, the dense greenery shields him. But as twilight deepens into frozen darkness, the paths twist into an impossible, confusing labyrinth. Exhausted, he walks endlessly only to find himself repeatedly circling back to the exact same spot.\n  </p>\n  <p>\n    Suddenly, his cynical rattrap theory flashes before his conscience like a stroke of lightning: <b style=\"color: #8E2DE2;\">he has succumbed to the bait of thirty kronor, and now the world's rattrap has snapped shut upon him</b>. The gigantic forest &mdash; with its interlocking trunks, fallen branches, and dense undergrowth &mdash; closes around him like an inescapable prison. Shivering from hypothermia and starvation, he collapses onto the frozen ground, waiting for biological death.\n  </p>\n\n  <h3 style=\"color: #8E2DE2; font-size: 17px; margin: 20px 0 10px 0;\">(iv) Ramsj&ouml; Ironworks &amp; The Mistaken Identity</h3>\n  <p>\n    As his head touches the frozen earth, the rhythmic, metallic thumping of an iron forge hammer reaches his ears. Summoning his remaining physical reserves, he staggers toward the sound, stumbling into the glowing cavern of the <b style=\"color: #8E2DE2;\">Ramsj&ouml; Ironworks</b>. Slipping past the indifferent master blacksmith and his apprentice, the vagabond slumps beside the radiant furnace to thaw his frozen limbs.\n  </p>\n  <p>\n    Shortly after, the aristocratic ironmaster arrives for his nightly inspection. In the murky glow of the blast furnace, the ironmaster catches sight of the bedraggled stranger. Examining his bearded, gaunt face, he mistakenly assumes the vagabond is his former regimental comrade from the army: <b style=\"color: #8E2DE2;\">Captain Nils Olof (von Stahle)</b>. Overcome with pity for his comrade's supposed fall from grace, the ironmaster ardently invites him to spend Christmas Eve at his manor.\n  </p>\n  <p>\n    The peddler, however, knows the stolen thirty kronor are burning in his pocket. Entering the ironmaster's manor feels like stepping voluntarily into a lion's den where the police will be summoned. Despite the owner’s insistent appeals, the peddler flatly refuses.\n  </p>\n\n  <h3 style=\"color: #8E2DE2; font-size: 17px; margin: 20px 0 10px 0;\">(v) Edla's Compassion &amp; The Daylight Revelation</h3>\n  <p>\n    Convinced that pride in his shabby rags prevents his comrade from accepting, the ironmaster dispatches his modest, compassionate daughter, <b style=\"color: #8E2DE2;\">Edla Willmansson</b>. Entering the forge, Edla gently lifts the tramp’s slouch hat. The man leaps to his feet in terrified panic.\n  </p>\n  <p>\n    Observing the terror in his eyes, Edla instantly discerns that this man is either a thief on the run or an escaped prison convict. Yet, speaking with profound gentleness and sincere Christian empathy, she promises: <i>\"You may be sure, Captain, that you will be allowed to leave us just as freely as you came. Only please stay with us over Christmas Eve.\"</i> Disarmed by her unfeigned warmth, the peddler accepts the valet’s fur coat and accompanies her carriage.\n  </p>\n  <p>\n    The following morning, after a hot bath, haircut, shave, and being dressed in a tailored suit and starched collar belonging to the ironmaster, the tramp enters the dining hall. In broad daylight, the ironmaster immediately perceives his catastrophic error: this stranger was never Captain von Stahle. Enraged, the ironmaster pounds the table, accusing him of deceit and threatening to hand him over to the sheriff.\n  </p>\n  <p>\n    The peddler stands tall and delivers his defiant philosophical rebuttal: <i>\"This whole world is nothing but a big rattrap... all good things are bits of cheese and pork set out to drag a poor fellow into trouble. A day may come when you yourself, Mr. Ironmaster, will want a big piece of pork and get caught in the trap!\"</i> Amused, the ironmaster laughs and orders him to leave. But just as the tramp reaches the door, Edla intercedes.\n  </p>\n\n  <h3 style=\"color: #8E2DE2; font-size: 17px; margin: 20px 0 10px 0;\">(vi) Edla's Intercession &amp; The Christmas Gift of Redemption</h3>\n  <p>\n    Edla insists that they cannot unceremoniously turn away a vulnerable human being whom they invited under promises of Christmas peace and goodwill. She wants him to enjoy a single day of undisturbed rest in the entire year. Her father reluctantly relents. Throughout Christmas Day, the peddler does nothing but sleep &mdash; enjoying uninterrupted tranquility for the first time in his hunted life.\n  </p>\n  <p>\n    The next morning at church, the ironmaster and Edla hear the scandalous news: an old crofter of Ramsj&ouml; works had been robbed of thirty kronor by a tramp selling rattraps. Convinced that their family silver and heirlooms have been stolen, the father berates Edla as they race home.\n  </p>\n  <p>\n    To their astonishment, the valet reports that the stranger left without taking a single pin. Instead, he left behind a roughly wrapped package for Miss Willmansson. Opening it, Edla finds:\n  </p>\n  <ul style=\"color: #CBD5E1; font-size: 14.5px; padding-left: 20px;\">\n    <li>A small wire rattrap.</li>\n    <li>Three wrinkled ten-kronor notes to be restored to the old crofter.</li>\n    <li>A letter addressed to Edla, written in jagged, earnest strokes:</li>\n  </ul>\n  <div style=\"background: rgba(142, 45, 226, 0.15); border-left: 4px solid #8E2DE2; padding: 14px 18px; margin: 16px 0; border-radius: 6px; font-style: italic; color: #F1F5F9; line-height: 1.8;\">\n    \"Honoured and noble Miss... since you have been so nice to me all day long, as if I was a real captain, I want to be nice to you in return... The rattrap is a Christmas present from a rat who would have been caught in this world’s rattrap if he had not been raised to captain, because in that way he got power to clear himself...<br/>\n    <b>Written with friendship and high respect, Captain von Stahle.</b>\"\n  </div>\n  <p>\n    By honoring him as a Captain, Edla conferred upon him the moral agency and dignity necessary to conquer his animal survival instinct. Love and respect broke the world's rattrap, redeeming his human soul.\n  </p>\n\n  <!-- Section 3: Literary Devices Master Table -->\n  <h2 style=\"color: #8E2DE2; font-size: 20px; font-weight: 800; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    3. Literary &amp; Rhetorical Devices Master Table\n  </h2>\n  <div style=\"overflow-x: auto; margin-bottom: 25px;\">\n    <table style=\"width: 100%; border-collapse: collapse; font-size: 14px; text-align: left; background: rgba(15, 23, 42, 0.9); border-radius: 8px; overflow: hidden;\">\n      <thead>\n        <tr style=\"background: rgba(142, 45, 226, 0.25); color: #FFFFFF; border-bottom: 2px solid #8E2DE2;\">\n          <th style=\"padding: 12px 14px;\">Literary Device</th>\n          <th style=\"padding: 12px 14px;\">Textual Quote / Example</th>\n          <th style=\"padding: 12px 14px;\">Thematic Function &amp; Critical Impact</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #8E2DE2;\">Extended Metaphor</td>\n          <td style=\"padding: 10px 14px;\">\"The whole world was nothing for him but a big rattrap.\"</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Anchors the entire moral narrative, equating worldly temptations with bait that ensnares human freedom.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #8E2DE2;\">Dramatic Irony</td>\n          <td style=\"padding: 10px 14px;\">The ironmaster treats a petty vagrant thief as his honored military comrade Captain von Stahle.</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Generates sharp narrative suspense and lays the psychological groundwork for the peddler's moral redemption.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #8E2DE2;\">Symbolism</td>\n          <td style=\"padding: 10px 14px;\">The Thirty Kronor vs. The Gifted Rattrap</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Thirty kronor represents moral capitulation to greed; the returned money and gifted rattrap signify spiritual liberation.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #8E2DE2;\">Foreshadowing</td>\n          <td style=\"padding: 10px 14px;\">\"The forest... closed in upon him like an impenetrable prison.\"</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Physical entrapment in the winter woods directly mirrors the psychological snare of guilt closing upon his soul.</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #8E2DE2;\">Allegory</td>\n          <td style=\"padding: 10px 14px;\">The Peddler's signature as 'Captain von Stahle'</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Illustrates that treating a fallen human being with dignity elevates their moral character to match that respect.</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n\n  <!-- Section 4: Thematic Pillars -->\n  <h2 style=\"color: #8E2DE2; font-size: 20px; font-weight: 800; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    4. Core Thematic Pillars &amp; Ethical Dimensions\n  </h2>\n  <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 14px;\">\n    <div style=\"background: rgba(142, 45, 226, 0.08); border-left: 4px solid #8E2DE2; padding: 14px; border-radius: 6px;\">\n      <h4 style=\"color: #FFFFFF; margin: 0 0 6px 0; font-size: 15.5px;\">Universal Human Goodness</h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 13.5px;\">No soul is inherently lost; criminal impulses are defense shields that dissolve when touched by genuine empathy.</p>\n    </div>\n    <div style=\"background: rgba(142, 45, 226, 0.08); border-left: 4px solid #8E2DE2; padding: 14px; border-radius: 6px;\">\n      <h4 style=\"color: #FFFFFF; margin: 0 0 6px 0; font-size: 15.5px;\">Conditional vs. Unconditional Grace</h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 13.5px;\">The ironmaster's hospitality vanishes with social status; Edla's compassion remains steadfast despite unmasking.</p>\n    </div>\n    <div style=\"background: rgba(142, 45, 226, 0.08); border-left: 4px solid #8E2DE2; padding: 14px; border-radius: 6px;\">\n      <h4 style=\"color: #FFFFFF; margin: 0 0 6px 0; font-size: 15.5px;\">The Snare of Worldly Temptation</h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 13.5px;\">Greed lures individuals into spiritual labyrinths; true liberation requires sacrificing ill-gotten gains.</p>\n    </div>\n  </div>\n\n</div>\n";

export const c12EngF4HtmlSolutions = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.8; color: #E2E8F0; max-width: 950px; margin: 0 auto; padding: 12px; font-size: 15.5px;\">\n\n  <!-- Solutions Header Badge -->\n  <div style=\"background: linear-gradient(135deg, rgba(142, 45, 226, 0.22), rgba(74, 0, 224, 0.1)); border: 1.5px solid #8E2DE2; border-radius: 12px; padding: 20px; margin-bottom: 25px; box-shadow: 0 4px 22px rgba(142, 45, 226, 0.15);\">\n    <div style=\"display: flex; align-items: center; gap: 10px; margin-bottom: 8px;\">\n      <span style=\"background: #8E2DE2; color: #FFFFFF; font-size: 12px; font-weight: 800; padding: 4px 10px; border-radius: 6px; letter-spacing: 0.5px;\">QUESTION BANK &bull; CHAPTER 4</span>\n      <span style=\"color: #94A3B8; font-size: 13.5px; font-weight: 600;\">CLASS XII ENGLISH CORE</span>\n    </div>\n    <h1 style=\"color: #FFFFFF; font-size: 24px; font-weight: 900; margin: 0 0 6px 0;\">The Rattrap &mdash; Complete Board Solutions</h1>\n    <p style=\"color: #CBD5E1; font-size: 14.5px; margin: 0;\">\n      Standardized for CBSE &amp; JKBOSE • High-Scoring Extract, Short, Long Thematic &amp; Official NCERT Solutions\n    </p>\n  </div>\n\n  <!-- SECTION A: EXTRACT-BASED QUESTIONS -->\n  <h2 style=\"color: #8E2DE2; font-size: 20px; font-weight: 800; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    SECTION A: Extract-Based Questions (16 Questions | 4 Extracts)\n  </h2>\n\n  <!-- Extract 1 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(142, 45, 226, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #8E2DE2;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #8E2DE2;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"The world had, of course, never been very kind to him, so it gave him unwonted joy to think ill of it in this way. It became a cherished pastime of his, during many dreary ploddings, to think of people he knew who had let themselves be caught in the dangerous snare, and of others who were still circling around the bait.\"\n    </p>\n    \n    <p>\n      <b style=\"color: #8E2DE2; font-size: 15px;\">Q1: What 'unwonted joy' did the peddler experience?</b><br/>\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> He felt malicious psychological pleasure in meditating that the cruel, inhospitable world was merely a gigantic rattrap waiting to trap others.\n    </p>\n\n    <p>\n      <b style=\"color: #8E2DE2; font-size: 15px;\">Q2: What is meant by people who were 'still circling around the bait'?</b><br/>\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> Greedy individuals who are increasingly tempted by worldly wealth, luxuries, and pleasures, hovering on the verge of moral entrapment.\n    </p>\n\n    <p>\n      <b style=\"color: #8E2DE2; font-size: 15px;\">Q3: Why was thinking ill of the world a 'cherished pastime' for him?</b><br/>\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> Because the world had consistently treated him with cruelty, neglect, and cold contempt; his cynical philosophy served as mental compensation.\n    </p>\n\n    <p>\n      <b style=\"color: #8E2DE2; font-size: 15px;\">Q4: Name the primary figure of speech operating throughout this extract.</b><br/>\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> Extended Metaphor (the world as a wire rattrap).\n    </p>\n  </div>\n\n  <!-- Extract 2 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(142, 45, 226, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #8E2DE2;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #8E2DE2;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"The next day both men got up in good season. The crofter was in a hurry to milk his cow, and the other man probably thought he should not stay in bed when the head of the house had gotten up. They left the cottage at the same time... But half an hour later the rattrap peddler stood again before the door. He did not try to get in. He only went up to the window, smashed a pane, stuck in his hand, and got hold of the pouch with the thirty kronor.\"\n    </p>\n    \n    <p>\n      <b style=\"color: #8E2DE2; font-size: 15px;\">Q5: Why did both men wake up early in the morning?</b><br/>\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> The crofter needed to milk his cow for his dairy income, and the peddler felt it improper to remain in bed after his generous host had risen.\n    </p>\n\n    <p>\n      <b style=\"color: #8E2DE2; font-size: 15px;\">Q6: Why did the peddler return thirty minutes after their departure?</b><br/>\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> He was overpowered by greed to steal the thirty kronor notes he had seen the trusting crofter stow in the leather pouch.\n    </p>\n\n    <p>\n      <b style=\"color: #8E2DE2; font-size: 15px;\">Q7: How did he gain access to the leather pouch without entering the house?</b><br/>\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> He smashed a windowpane, reached his arm through the shattered glass, and unhooked the pouch from the nail.\n    </p>\n\n    <p>\n      <b style=\"color: #8E2DE2; font-size: 15px;\">Q8: What moral betrayal occurred in this incident?</b><br/>\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> The violation of sacred hospitality and innocent trust extended by a lonely, benevolent old man.\n    </p>\n  </div>\n\n  <!-- Extract 3 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(142, 45, 226, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #8E2DE2;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #8E2DE2;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"The young girl stood there quite embarrassed and hardly knew what to say. That morning she had felt so happy when she thought how homelike and Christmassy she was going to make things for the poor hungry wretch. She could not get away from the idea all at once, and that was why she had interceded for the vagabond.\"\n    </p>\n    \n    <p>\n      <b style=\"color: #8E2DE2; font-size: 15px;\">Q9: Why did Edla Willmansson intercede on behalf of the vagabond?</b><br/>\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> She had anticipated giving a destitute, homeless wanderer Christmas warmth and joy, and refused to revoke that humane promise.\n    </p>\n\n    <p>\n      <b style=\"color: #8E2DE2; font-size: 15px;\">Q10: Why was her father furiously determined to eject the stranger?</b><br/>\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> In broad daylight, he discovered that the stranger was not his military comrade Captain von Stahle, but an imposter.\n    </p>\n\n    <p>\n      <b style=\"color: #8E2DE2; font-size: 15px;\">Q11: What character virtue does Edla manifest through this action?</b><br/>\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> True Christian charity, moral conviction, and selfless compassion that transcends social status and rank.\n    </p>\n\n    <p>\n      <b style=\"color: #8E2DE2; font-size: 15px;\">Q12: What was the ultimate consequence of Edla's compassionate intervention?</b><br/>\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> It unlocked the peddler's dormant conscience, inspiring his moral rebirth and the return of the stolen money.\n    </p>\n  </div>\n\n  <!-- Extract 4 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(142, 45, 226, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #8E2DE2;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #8E2DE2;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"The rattrap is a Christmas present from a rat who would have been caught in this world’s rattrap if he had not been raised to captain, because in that way he got power to clear himself. Written with friendship and high respect, Captain von Stahle.\"\n    </p>\n    \n    <p>\n      <b style=\"color: #8E2DE2; font-size: 15px;\">Q13: Who is the 'rat' referred to in this letter?</b><br/>\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> The destitute peddler himself, who had succumbed to worldly bait and almost perished in moral darkness.\n    </p>\n\n    <p>\n      <b style=\"color: #8E2DE2; font-size: 15px;\">Q14: How did being 'raised to captain' give him the power to clear himself?</b><br/>\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> Being treated with chivalric honor and unconditional dignity elevated his self-respect, empowering him to overcome his animal instincts and act honorably.\n    </p>\n\n    <p>\n      <b style=\"color: #8E2DE2; font-size: 15px;\">Q15: What items were enclosed alongside this letter?</b><br/>\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> A small wire rattrap and the three stolen ten-kronor notes to be returned to the old crofter.\n    </p>\n\n    <p>\n      <b style=\"color: #8E2DE2; font-size: 15px;\">Q16: Why did he sign his name as 'Captain von Stahle'?</b><br/>\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> To show that he had internalized the nobility and integrity of a true Captain, responding to Edla's faith with genuine gentlemanly virtue.\n    </p>\n  </div>\n\n  <!-- SECTION B: SHORT ANSWER QUESTIONS -->\n  <h2 style=\"color: #8E2DE2; font-size: 20px; font-weight: 800; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION B: Short Answer Questions (3 Marks Each | 40&ndash;50 Words)\n  </h2>\n\n  <!-- Q17 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q17: From where did the peddler derive his philosophy of the world being a rattrap?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> While trudging along the snow-covered roads meditating on his wire rattraps, he struck upon the whimsical analogy that the whole world was a giant rattrap setting baits of wealth, food, and joy for human beings, just as cheese attracts rats.\n    </p>\n  </div>\n\n  <!-- Q18 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q18: Why was the old crofter so talkative and generous to the wandering peddler?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> The crofter lived in solitary isolation in his roadside cottage without wife or children. Starved of human warmth and companionship, he was overjoyed to welcome someone to converse with during the gloomy winter evening, sharing his porridge and tobacco.\n    </p>\n  </div>\n\n  <!-- Q19 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q19: How did the peddler betray the old crofter's generous hospitality?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> Succumbing to base greed, the peddler returned thirty minutes after their cordial morning departure, smashed the windowpane with his fist, extracted the leather pouch from the wall nail, stole the thirty kronor, and fled.\n    </p>\n  </div>\n\n  <!-- Q20 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q20: How did the dense forest turn into an actual rattrap for the peddler?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> Fearing arrest on the highway, he entered the pathless woods. The twisting paths repeatedly led him in circles back to the same spot. He realized that the stolen thirty kronor had served as bait, and the dense forest had trapped him like an iron cage.\n    </p>\n  </div>\n\n  <!-- Q21 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q21: Why did the ironmaster mistake the peddler for Captain Nils Olof von Stahle?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> Inside the dimly illuminated Ramsj&ouml; forge, the flickering furnace glow cast deceptive shadows over the tramp's ragged figure and bearded visage. Expecting his lost regimental comrade, the ironmaster jumped to a mistaken conclusion.\n    </p>\n  </div>\n\n  <!-- Q22 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q22: Why did the peddler adamantly decline the ironmaster's invitation to the manor?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> With the stolen thirty kronor concealed in his pocket, entering the ironmaster's aristocratic manor house felt like walking voluntarily into a lion's den, where discovery by the police would mean certain imprisonment.\n    </p>\n  </div>\n\n  <!-- Q23 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q23: What did Edla deduce about the peddler upon seeing his frightened reaction in the forge?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> When Edla lifted his hat and saw his wild, terrified start, she perceptively deduced that the man had either committed a theft or was a fugitive convict who had escaped from prison.\n    </p>\n  </div>\n\n  <!-- Q24 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q24: How did the peddler defend himself when his real identity was exposed in broad daylight?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> He stated that he had never claimed to be an officer and had begged to remain in the forge. He warned the ironmaster that the whole world was a rattrap, and that one day the ironmaster himself would be ensnared by some tempting bait.\n    </p>\n  </div>\n\n  <!-- Q25 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q25: Why did Edla insist on hosting the vagabond despite knowing he was an imposter?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> Edla believed it was hypocritical and cruel to invite a lonely, persecuted human being with promises of Christmas cheer and then cast him back into the freezing snow. She wanted him to enjoy one peaceful day of rest in the entire year.\n    </p>\n  </div>\n\n  <!-- Q26 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q26: What shocking revelation did the ironmaster and Edla learn at church on Christmas morning?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> They learned that an old crofter of Ramsj&ouml; works had been robbed of thirty kronor by a tramp selling wire rattraps, confirming that their houseguest was indeed a petty thief.\n    </p>\n  </div>\n\n  <!-- Q27 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q27: What was inside the package left behind by the peddler for Edla?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> Inside the roughly wrapped package lay a small wire rattrap containing three wrinkled ten-kronor notes for the crofter and an affectionate, dignified letter signed as 'Captain von Stahle'.\n    </p>\n  </div>\n\n  <!-- Q28 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q28: Why did the peddler sign his farewell letter as 'Captain von Stahle'?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> Because Edla had treated him with the chivalric honor and respect due to an army captain, he felt morally elevated above his criminal past. Signing as Captain von Stahle demonstrated that he was reciprocating her trust with true gentlemanly virtue.\n    </p>\n  </div>\n\n  <!-- SECTION C: LONG ANSWER QUESTIONS -->\n  <h2 style=\"color: #8E2DE2; font-size: 20px; font-weight: 800; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION C: Long Answer Questions (6 Marks Each | 120&ndash;150 Words)\n  </h2>\n\n  <!-- Q29 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(142, 45, 226, 0.3); border-radius: 8px; padding: 18px; margin-bottom: 22px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16.5px; margin: 0 0 10px 0; font-weight: 800;\">Q29: How does the extended metaphor of the rattrap serve as the philosophical backbone of Selma Lagerl&ouml;f's story?</h4>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.8;\">\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #8E2DE2;\">Introduction &amp; Conceptual Formulation:</b><br/>\n        The metaphor of the rattrap is the central structural and moral foundation of the entire narrative. What begins as an eccentric mental pastime of an embittered vagabond evolves into an allegory on human greed, moral entrapment, and divine redemption.\n      </p>\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #8E2DE2;\">Literal &amp; Psychological Entrapment:</b><br/>\n        The vagabond initially views the world cynically: wealth, food, and joy are tempting baits set to lure vulnerable humans into despair. Ironically, he falls victim to his own theory when he steals the thirty kronor from the trusting crofter. This money becomes his bait; fleeing the highway, he is ensnared within the impenetrable maze of the winter woods, which physically traps him just like an iron cage.\n      </p>\n      <p style=\"margin: 0;\">\n        <b style=\"color: #8E2DE2;\">Redemption &amp; Moral Release:</b><br/>\n        Ultimately, the metaphor provides the instrument of his salvation. In his farewell letter, he gifts Edla a rattrap, thanking her for raising him to the stature of a captain, which granted him the dignity to slip out of the world’s rattrap. Thus, the metaphor links cynicism, moral fall, and spiritual liberation.\n      </p>\n    </div>\n  </div>\n\n  <!-- Q30 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(142, 45, 226, 0.3); border-radius: 8px; padding: 18px; margin-bottom: 22px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16.5px; margin: 0 0 10px 0; font-weight: 800;\">Q30: Compare and contrast the characters, motivations, and ethical outlooks of the Ironmaster and his daughter, Edla Willmansson.</h4>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.8;\">\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #8E2DE2;\">The Ironmaster &mdash; Conditional &amp; Status-Driven:</b><br/>\n        The Ironmaster represents superficial, status-conscious benevolence. His hospitality is conditional: he invites the tramp solely because he mistakes him for an aristocratic military comrade of his own social standing. When broad daylight exposes the man as an impoverished vagrant, his kindness instantly turns to rage, accusations of dishonesty, and threats of police action.\n      </p>\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #8E2DE2;\">Edla Willmansson &mdash; Unconditional Christian Grace:</b><br/>\n        In sharp contrast, Edla embodies pure, selfless empathy. Even after suspecting the tramp of being a thief or convict at the forge, she speaks with deep gentleness. When his deception is laid bare, she courageously defies her father, arguing that human hospitality cannot be revoked simply because someone is destitute and unworthy.\n      </p>\n      <p style=\"margin: 0;\">\n        <b style=\"color: #8E2DE2;\">Critical Verdict:</b><br/>\n        While the ironmaster judges by appearances and social class, Edla perceives the sacred worth of the human soul, making her the catalyst of the peddler's moral resurrection.\n      </p>\n    </div>\n  </div>\n\n  <!-- Q31 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(142, 45, 226, 0.3); border-radius: 8px; padding: 18px; margin-bottom: 22px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16.5px; margin: 0 0 10px 0; font-weight: 800;\">Q31: \"The essential goodness in a human being can be awakened through understanding and love.\" Discuss with close reference to 'The Rattrap'.</h4>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.8;\">\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #8E2DE2;\">Selma Lagerl&ouml;f's Ethical Thesis:</b><br/>\n        Lagerl&ouml;f’s master theme is that moral degradation and criminal inclinations are often defensive responses to chronic societal neglect and hostility. Within every fallen human lies an innate core of goodness that punishment cannot reach, but love and empathy can revive.\n      </p>\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #8E2DE2;\">The Peddler's Degradation &amp; Elevation:</b><br/>\n        Treated as an outcast, the peddler steals the crofter's thirty kronor out of base survival instinct. However, when brought to the manor, Edla treats him not with condescending charity, but with sincere chivalric honor. She defends him against her father and gifts him the Christmas suit and undisturbed peace.\n      </p>\n      <p style=\"margin: 0;\">\n        <b style=\"color: #8E2DE2;\">The Moral Metamorphosis:</b><br/>\n        This unearned grace touches his core. Instead of stealing the family silver, he departs leaving behind the stolen thirty kronor to be returned, accompanied by a letter signed as Captain von Stahle. Edla’s faith proved that love is infinitely more restorative than condemnation.\n      </p>\n    </div>\n  </div>\n\n  <!-- Q32 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(142, 45, 226, 0.3); border-radius: 8px; padding: 18px; margin-bottom: 22px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16.5px; margin: 0 0 10px 0; font-weight: 800;\">Q32: Trace the psychological progression of the peddler from cynical vagabond to redeemed gentleman.</h4>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.8;\">\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #8E2DE2;\">Phase 1: Cynical Alienation:</b><br/>\n        Initially, the peddler lives as a hunted animal, harboring bitter resentment against society and nursing malicious satisfaction in viewing humanity as trapped in a wire snare.\n      </p>\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #8E2DE2;\">Phase 2: Moral Guilt &amp; Panic:</b><br/>\n        After stealing the thirty kronor, he becomes terrified of arrest. Entrapped in the winter woods, his cynicism collapses into paralyzing self-reproach as he realizes he has taken the bait and is doomed.\n      </p>\n      <p style=\"margin: 0;\">\n        <b style=\"color: #8E2DE2;\">Phase 3: Spiritual Elevation:</b><br/>\n        Touched by Edla's unwavering respect and refusal to cast him out, his dormant nobility surfaces. He discards the petty thief's mindset, returns the stolen money, and signs as Captain von Stahle &mdash; completing his transformation into a man of honor.\n      </p>\n    </div>\n  </div>\n\n  <!-- Q33 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(142, 45, 226, 0.3); border-radius: 8px; padding: 18px; margin-bottom: 22px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16.5px; margin: 0 0 10px 0; font-weight: 800;\">Q33: How does Selma Lagerl&ouml;f weave folkloric and fairy-tale elements into a realistic story of Swedish mining life?</h4>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.8;\">\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #8E2DE2;\">Fairy-Tale Structure:</b><br/>\n        The story opens with the traditional cadence: <i>\"Once upon a time there was a man...\"</i> It features archetypal fairy-tale motifs: a lonely cottage in the woods, an enchanted dark forest trap, a mysterious forge in the night, and a benevolent maiden whose virtue breaks a spell.\n      </p>\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #8E2DE2;\">Socio-Economic Realism:</b><br/>\n        Simultaneously, Lagerl&ouml;f roots the tale in historical reality &mdash; the iron foundries of Bergslagen, the struggles of tenant crofters displaced by industrialization, and the harsh winter survival of vagrants.\n      </p>\n      <p style=\"margin: 0;\">\n        <b style=\"color: #8E2DE2;\">Critical Verdict:</b><br/>\n        By merging the moral simplicity of folklore with gritty socio-economic realism, Lagerl&ouml;f creates a timeless universal parable of human redemption.\n      </p>\n    </div>\n  </div>\n\n  <!-- Q34 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(142, 45, 226, 0.3); border-radius: 8px; padding: 18px; margin-bottom: 22px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16.5px; margin: 0 0 10px 0; font-weight: 800;\">Q34: Analyze the peddler's speech about the world being a rattrap delivered to the enraged ironmaster.</h4>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.8;\">\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #8E2DE2;\">Context of the Confrontation:</b><br/>\n        When the ironmaster discovers his identity in broad daylight and threatens to summon the sheriff, the peddler refuses to cringe in fear. Instead, he strikes the table and delivers a philosophical indictment.\n      </p>\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #8E2DE2;\">The Egalitarian Warning:</b><br/>\n        He warns the ironmaster that all the wealth and status he enjoys are mere \"cheese rinds and bits of pork\" designed to drag individuals into traps. He boldly cautions that a day may come when the ironmaster himself will desire some tempting prize and get caught in the world's snare.\n      </p>\n      <p style=\"margin: 0;\">\n        <b style=\"color: #8E2DE2;\">Significance:</b><br/>\n        This speech levels the moral playing field between the wealthy industrialist and the ragged vagabond, demonstrating that all human beings are equally vulnerable to temptation and ruin.\n      </p>\n    </div>\n  </div>\n\n  <!-- SECTION D: NCERT TEXTBOOK EXERCISES -->\n  <h2 style=\"color: #8E2DE2; font-size: 20px; font-weight: 800; border-bottom: 2px solid #8E2DE2; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION D: NCERT Textbook Exercises (Think As You Read &amp; Understanding The Text)\n  </h2>\n\n  <!-- Q35 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q35: What made the peddler accept Edla Willmansson's invitation to the manor house?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> Edla spoke to him with genuine tenderness, compassion, and respect. She assured him that he would be allowed to leave just as freely as he arrived, which won his confidence and persuaded him to accompany her carriage.\n    </p>\n  </div>\n\n  <!-- Q36 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q36: What doubts did Edla have about the peddler when she first saw him in the forge?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> When Edla lifted his hat at the forge and saw his wild, terrified expression, she felt that the man looked deeply afraid, suspecting that he had either stolen something or escaped from prison.\n    </p>\n  </div>\n\n  <!-- Q37 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q37: When did the ironmaster realize his mistake regarding the stranger's identity?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> The next morning, when the stranger had been bathed, groomed, cleanly shaved, and dressed in the ironmaster's tailored suit, the ironmaster saw him in broad daylight and instantly realized he was a total stranger.\n    </p>\n  </div>\n\n  <!-- Q38 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #8E2DE2;\">\n    <h4 style=\"color: #8E2DE2; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q38: What did the peddler leave behind as a Christmas gift for Edla, and why?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #8E2DE2; font-weight: bold;\">✓ Answer:</span> He left behind a small wire rattrap containing the stolen thirty kronor in three ten-kronor notes, along with an affectionate letter addressed to Edla. He did this because her unconditional kindness had elevated him to the stature of a gentleman, inspiring him to cleanse his conscience.\n    </p>\n  </div>\n\n</div>\n";

